# Generated by build_secure_install.py. Run ONCE from an elevated PowerShell (Run as administrator):
#   pwsh -NoProfile -ExecutionPolicy Bypass -File "C:\Users\mesue\Documents\Scripts\MonitorWidget\install_secure_2026-10-24.ps1"
#   add -RemoveLegacy to also delete MemoryPurge-OnDemand and MonitorWidget-BootTrace.
# What it does: verifies the SHA256 of each source, copies it into a protected folder, builds purge.exe from the
# protected copy, sets ACLs (admins/SYSTEM full, users read+execute), registers tasks that run ONLY from there,
# and pins the hash of the orphan-reaper script. Nothing else on the system is touched.
param([switch]$RemoveLegacy)
$ErrorActionPreference = 'Stop'
$id = [Security.Principal.WindowsIdentity]::GetCurrent()
if (-not ([Security.Principal.WindowsPrincipal]$id).IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)) { throw 'Run as administrator.' }

$src    = 'C:\Users\mesue\Documents\Scripts\MonitorWidget'
$secure = 'C:\ProgramData\MonitorWidget'
$bin = Join-Path $secure 'bin'; $out = Join-Path $secure 'out'
$pwsh = 'C:\Program Files\PowerShell\7\pwsh.exe'
$csc  = 'C:\Windows\Microsoft.NET\Framework64\v4.0.30319\csc.exe'
$expected = @{
  'purge.cs' = 'D7C934CB7F2C611748AC67128F2FEDD52033B96E7D580060E2004930A0E91F4F'
  'healthprobe.ps1' = 'F37D177EC6D386CFAE96A00BD49890C35B9B28FD404307C2FFB6D0CA574FB53E'
  'winold_delete.ps1' = 'D338ABDBDA50AA7D6D7FB1D4DC5DF94F48687D747304BC761B9C5BB54B5D9FAE'
  'elevated_clean.ps1' = 'BAB443DE631D2D64D0562E256D15EE41B8E723E9ED78A0776CC2D6D6C62869A3'
  'gpu_dwm_restart.ps1' = 'A3E2465CE7C3CCED2FB43FA25A3F037BE1F0E8AA5AD82DED010440B8EB9945BD'
  'mwsafedel.cs' = '4F1BE3F38ED35755DBF245F6EE6B81E8AEB141072C82468812E56F0F0CC0DB60'
}
$reaper = 'C:\Users\mesue\Documents\Scripts\MachineCare\Invoke-OrphanReaper.ps1'; $reaperHash = '8104AE8B121F55E07119E070EEB014B31581E97945A3A65EF0329BB1D66F5F25'

# 1. verify sources before copying anything
foreach ($k in $expected.Keys) {
  $h = (Get-FileHash -Algorithm SHA256 -LiteralPath (Join-Path $src $k)).Hash
  if ($h -ne $expected[$k]) { throw "Hash mismatch for $k (expected $($expected[$k]), got $h). Regenerate with build_secure_install.py after review." }
}
if ($reaperHash) {
  $rh = (Get-FileHash -Algorithm SHA256 -LiteralPath $reaper).Hash
  if ($rh -ne $reaperHash) { throw "Hash mismatch for the reaper script ($rh). Review it, then regenerate." }
}

# 2. folders + ACL (SIDs, language independent): SYSTEM, Administrators full; Users read+execute
New-Item -ItemType Directory -Force -Path $bin, $out | Out-Null
foreach ($d in @($secure, $bin, $out)) {
  # S-1-3-4 (OWNER RIGHTS): يلغي حق المالك الضمني في تغيير الصلاحيات؛ ما ينشئه المسؤول بحساب المالك يملكه الحساب نفسه (ثغرة 19/11)
  & icacls.exe $d /inheritance:r /grant:r '*S-1-5-18:(OI)(CI)F' '*S-1-5-32-544:(OI)(CI)F' '*S-1-5-32-545:(OI)(CI)RX' '*S-1-3-4:(OI)(CI)RX' | Out-Null
  if ($LASTEXITCODE -ne 0) { throw "icacls failed on $d" }
}

# 3. copy and build from the protected copy, then verify what is there
Copy-Item -LiteralPath (Join-Path $src 'purge.cs') -Destination (Join-Path $bin 'purge.cs') -Force
Copy-Item -LiteralPath (Join-Path $src 'healthprobe.ps1') -Destination (Join-Path $bin 'healthprobe.ps1') -Force
Copy-Item -LiteralPath (Join-Path $src 'winold_delete.ps1') -Destination (Join-Path $bin 'winold_delete.ps1') -Force
Copy-Item -LiteralPath (Join-Path $src 'elevated_clean.ps1') -Destination (Join-Path $bin 'elevated_clean.ps1') -Force
Copy-Item -LiteralPath (Join-Path $src 'gpu_dwm_restart.ps1') -Destination (Join-Path $bin 'gpu_dwm_restart.ps1') -Force
Copy-Item -LiteralPath (Join-Path $src 'mwsafedel.cs') -Destination (Join-Path $bin 'mwsafedel.cs') -Force
& $csc /nologo /target:winexe /optimize+ "/out:$bin\purge.exe" "$bin\purge.cs"
if ($LASTEXITCODE -ne 0) { throw 'csc failed' }
foreach ($k in $expected.Keys) {
  if ((Get-FileHash -Algorithm SHA256 -LiteralPath (Join-Path $bin $k)).Hash -ne $expected[$k]) { throw "Copied $k differs from the reviewed source" }
}
$exeHash = (Get-FileHash -Algorithm SHA256 -LiteralPath "$bin\purge.exe").Hash
@{ purge_exe_sha256 = $exeHash; installed = (Get-Date).ToString('s') } | ConvertTo-Json | Set-Content -LiteralPath "$out\install_manifest.json" -Encoding UTF8
if ($reaperHash) {
  @{ sha256 = $reaperHash; script = $reaper } | ConvertTo-Json | Set-Content -LiteralPath "$out\reaper_pin.json" -Encoding UTF8
}
& icacls.exe $secure /setowner '*S-1-5-32-544' /T /C /Q | Out-Null   # الملكية للمسؤولين: لا مالك عاديّ يغيّر صلاحيات ما في bin وout

# 4. tasks: fixed argument per mode, no file next to the exe is trusted
$user = "$env:USERDOMAIN\$env:USERNAME"
$pr = New-ScheduledTaskPrincipal -UserId $user -LogonType Interactive -RunLevel Highest
$set = New-ScheduledTaskSettingsSet -AllowStartIfOnBatteries -DontStopIfGoingOnBatteries -ExecutionTimeLimit (New-TimeSpan -Minutes 3) -MultipleInstances IgnoreNew -Hidden
foreach ($m in @('light')) {   # item 24: standby and deep were removed
  $name = 'MemoryPurge-' + (Get-Culture).TextInfo.ToTitleCase($m)
  $act = New-ScheduledTaskAction -Execute "$bin\purge.exe" -Argument "$m `"$out\purge_result.json`"" -WorkingDirectory $bin
  Register-ScheduledTask -TaskName $name -Action $act -Principal $pr -Settings $set -Description "On-demand RAM purge, mode=$m (protected install)" -Force | Out-Null
}
foreach ($n in 'MemoryPurge-Standby','MemoryPurge-Deep') {
  if (Get-ScheduledTask -TaskName $n -ErrorAction SilentlyContinue) { Unregister-ScheduledTask -TaskName $n -Confirm:$false }
}
$cmd = "& '$bin\healthprobe.ps1' -SkipUpdates | Set-Content -LiteralPath '$out\admin_probe.json' -Encoding UTF8"
$a  = New-ScheduledTaskAction -Execute $pwsh -Argument "-NoProfile -WindowStyle Hidden -ExecutionPolicy RemoteSigned -Command `"$cmd`"" -WorkingDirectory $bin
$t1 = New-ScheduledTaskTrigger -AtLogOn -User $env:USERNAME
$t2 = New-ScheduledTaskTrigger -Once -At (Get-Date).AddMinutes(1) -RepetitionInterval (New-TimeSpan -Minutes 30) -RepetitionDuration (New-TimeSpan -Days 3650)
$ps = New-ScheduledTaskSettingsSet -AllowStartIfOnBatteries -DontStopIfGoingOnBatteries -StartWhenAvailable -MultipleInstances IgnoreNew -ExecutionTimeLimit (New-TimeSpan -Minutes 5)
Register-ScheduledTask -TaskName 'MonitorWidget-AdminProbe' -Action $a -Trigger @($t1, $t2) -Principal $pr -Settings $ps -Description 'Read-only hardware probe, runs from the protected folder' -Force | Out-Null

# 4b. Windows.old: two fixed on-demand tasks (normal = 14-day gate inside the script, early = owner-confirmed override); no path argument
$ws = New-ScheduledTaskSettingsSet -AllowStartIfOnBatteries -DontStopIfGoingOnBatteries -ExecutionTimeLimit (New-TimeSpan -Hours 3) -MultipleInstances IgnoreNew -Hidden
foreach ($e in @($false, $true)) {
  $name = if ($e) { 'MonitorWidget-WinOld-Early' } else { 'MonitorWidget-WinOld' }
  $arg = "-NoProfile -WindowStyle Hidden -ExecutionPolicy RemoteSigned -File `"$bin\winold_delete.ps1`" -Result `"$out\winold_result.json`"" + $(if ($e) { ' -Early' } else { '' })
  $wa = New-ScheduledTaskAction -Execute $pwsh -Argument $arg -WorkingDirectory $bin
  Register-ScheduledTask -TaskName $name -Action $wa -Principal $pr -Settings $ws -Description 'On-demand Windows.old removal from the protected folder (fixed path, 14-day gate)' -Force | Out-Null
}

# 4c. elevated cleanups (Windows\Temp, SoftwareDistribution\Download, DISM StartComponentCleanup): one fixed on-demand task per kind,
#     the kind is baked into the task argument; the server passes nothing. Disabled kinds are refused by the server (settings switch).
$cs = New-ScheduledTaskSettingsSet -AllowStartIfOnBatteries -DontStopIfGoingOnBatteries -ExecutionTimeLimit (New-TimeSpan -Hours 2) -MultipleInstances IgnoreNew -Hidden
foreach ($k in @(@('wintemp', 'MonitorWidget-Clean-WinTemp'), @('swdist', 'MonitorWidget-Clean-SwDist'), @('dism', 'MonitorWidget-Clean-Dism'))) {
  $arg = "-NoProfile -WindowStyle Hidden -ExecutionPolicy RemoteSigned -File `"$bin\elevated_clean.ps1`" -Kind $($k[0]) -Result `"$out\clean_$($k[0])_result.json`""
  $ca = New-ScheduledTaskAction -Execute $pwsh -Argument $arg -WorkingDirectory $bin
  Register-ScheduledTask -TaskName $k[1] -Action $ca -Principal $pr -Settings $cs -Description "On-demand elevated cleanup ($($k[0])) from the protected folder; fixed kind, no path argument" -Force | Out-Null
}

# 4d. graphics memory: restart the desktop window manager (dwm) to release the shared GPU memory it holds (Intel driver leak).
#     Windows restarts dwm at once; no program is closed. Fixed script, no argument from the server, 2-minute gap inside the script.
$gs = New-ScheduledTaskSettingsSet -AllowStartIfOnBatteries -DontStopIfGoingOnBatteries -ExecutionTimeLimit (New-TimeSpan -Minutes 2) -MultipleInstances IgnoreNew -Hidden
$garg = "-NoProfile -WindowStyle Hidden -ExecutionPolicy RemoteSigned -File `"$bin\gpu_dwm_restart.ps1`" -Result `"$out\clean_dwm_result.json`""
$ga = New-ScheduledTaskAction -Execute $pwsh -Argument $garg -WorkingDirectory $bin
Register-ScheduledTask -TaskName 'MonitorWidget-Gpu-Dwm' -Action $ga -Principal $pr -Settings $gs -Description 'On-demand dwm restart to release shared GPU memory (protected folder, fixed script)' -Force | Out-Null

# 4e. orphan reaper: two fixed on-demand tasks at the user's own LIMITED privilege (dry / apply baked into the argument).
#     The script lives in the user-writable MachineCare folder, so it must never run elevated; the elevated server only triggers
#     these tasks after checking the pinned hash, and reads the result from the MachineCare log. conhost --headless: no window.
$rpr = New-ScheduledTaskPrincipal -UserId $user -LogonType Interactive -RunLevel Limited
$rs = New-ScheduledTaskSettingsSet -AllowStartIfOnBatteries -DontStopIfGoingOnBatteries -ExecutionTimeLimit (New-TimeSpan -Minutes 3) -MultipleInstances IgnoreNew -Hidden
foreach ($k in @(@('-DryRun', 'MonitorWidget-Reaper-Dry'), @('-Apply', 'MonitorWidget-Reaper-Apply'))) {
  $ra = New-ScheduledTaskAction -Execute "$env:SystemRoot\System32\conhost.exe" -Argument "--headless `"$pwsh`" -NoProfile -ExecutionPolicy RemoteSigned -File `"$reaper`" $($k[0])" -WorkingDirectory (Split-Path $reaper)
  Register-ScheduledTask -TaskName $k[1] -Action $ra -Principal $rpr -Settings $rs -Description "On-demand orphan reaper ($($k[0])) at limited user privilege; triggered by the monitor server" -Force | Out-Null
}

# 5. optional: remove the legacy tasks that ran from the writable folder
if ($RemoveLegacy) {
  foreach ($n in 'MemoryPurge-OnDemand','MonitorWidget-BootTrace') {
    if (Get-ScheduledTask -TaskName $n -ErrorAction SilentlyContinue) { Unregister-ScheduledTask -TaskName $n -Confirm:$false }
  }
}

Start-ScheduledTask -TaskName 'MonitorWidget-AdminProbe'
Write-Host "Installed. purge.exe sha256 = $exeHash"
Write-Host 'Now restart the monitor server (restart_agent.ps1) so it picks up the protected paths.'
